// boss_art.h — shared "giant invader" boss bodies. Every game's boss renders
// its body as one of these scaled-up pixel-art aliens (instead of a plain block),
// then overlays its own googly eyes / mouth / crown for personality.
#pragma once

#include <algorithm>
#include <string>
#include <vector>

#include "color.h"
#include "surface.h"

