// Render giant-alien sprite `idx` (frame 0/1) scaled into box (bx,by,bw,bh) in
// `body` colour. `brick` adds a lit top-edge per cell (a "made of bricks" look).
//
// The body is drawn as a bright neon RIM (the silhouette outline) over a darker
// interior, with a soft glow halo that only hugs the rim cells. That way the CRT
// bloom traces the creature's shape instead of flooding the whole filled area
// into one solid glowing block.
inline void draw_boss_alien(Surface& s, int idx, int frame, int bx, int by,
                            int bw, int bh, Color body, bool brick = false) {
    idx = std::clamp(idx, 0, 3);
    const auto& spr = BOSS_ALIEN[idx][frame & 1];
    int rows = (int)spr.size(), cols = 0;
    for (auto& r : spr) cols = std::max(cols, (int)r.size());
    if (rows == 0 || cols == 0) return;
    float cw = bw / float(cols), chh = bh / float(rows);
    int cellw = int(cw) + 1, cellh = int(chh) + 1;
    Color rim(std::min(255, body.r + 60), std::min(255, body.g + 60), std::min(255, body.b + 60));
    // Two interior shades give the body form (a beveled, plated look) instead of a
    // flat dark fill — the cells just inside the rim are mid-bright, the deep
    // interior is dark. With the high-res grids this is what reads as "HD".
    Color mid(int(body.r * 0.80f), int(body.g * 0.80f), int(body.b * 0.80f));
    Color core(int(body.r * 0.45f), int(body.g * 0.45f), int(body.b * 0.45f));

    auto filled = [&](int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < (int)spr[r].size() && spr[r][c] == '#';
    };
    auto is_rim = [&](int r, int c) {
        return !filled(r - 1, c) || !filled(r + 1, c) || !filled(r, c - 1) || !filled(r, c + 1);
    };
    // A cell is "mid" (the bevel) when it is interior but touches the rim — i.e.
    // one of its 4 neighbours is a rim cell. Deep-interior cells stay "core".
    auto is_mid = [&](int r, int c) {
        return is_rim(r - 1, c) || is_rim(r + 1, c) || is_rim(r, c - 1) || is_rim(r, c + 1);
    };

    // Pass 1 — soft halo under rim cells only, so the glow follows the outline.
    int gw = cellw + std::max(2, cellw / 2), gh = cellh + std::max(2, cellh / 2);
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < (int)spr[r].size(); ++c)
            if (spr[r][c] == '#' && is_rim(r, c)) {
                int px = bx + int(c * cw), py = by + int(r * chh);
                draw::rect(s, Color(rim.r, rim.g, rim.b, 55), {px - gw / 5, py - gh / 5, gw, gh});
            }
    // Pass 2 — bright rim outline over a darker interior (form, not a flat block).
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < (int)spr[r].size(); ++c)
            if (spr[r][c] == '#') {
                int px = bx + int(c * cw), py = by + int(r * chh);
                Color cell = is_rim(r, c) ? rim : (is_mid(r, c) ? mid : core);
                draw::rect(s, cell, {px, py, cellw, cellh});
                if (brick) draw::rect(s, rim, {px, py, cellw, std::max(2, cellh / 4)});
            }
}
